package com.msp.problemdetails;

import java.net.URI;
import java.util.*;

/**
 * Representation of RFC 7807 and RFC 9457 Problem Details for HTTP APIs.
 *
 * <p>Standard members:</p>
 * <ul>
 *   <li><b>type</b>: A URI reference identifying the problem type (defaults to "about:blank").</li>
 *   <li><b>title</b>: A short, human-readable summary of the problem type.</li>
 *   <li><b>status</b>: The HTTP status code generated by the origin server for this occurrence.</li>
 *   <li><b>detail</b>: A human-readable explanation specific to this occurrence of the problem.</li>
 *   <li><b>instance</b>: A URI reference that identifies the specific occurrence of the problem.</li>
 * </ul>
 *
 * <p>Also supports arbitrary extension members (e.g. invalidParams, traceId, errorCode).</p>
 */
public final class ProblemDetails {

    public static final String MEDIA_TYPE_JSON = "application/problem+json";
    public static final String MEDIA_TYPE_XML = "application/problem+xml";
    public static final URI DEFAULT_TYPE = URI.create("about:blank");

    private final URI type;
    private final String title;
    private final Integer status;
    private final String detail;
    private final URI instance;
    private final Map<String, Object> extensions;

    private ProblemDetails(URI type, String title, Integer status, String detail, URI instance, Map<String, Object> extensions) {
        this.type = type != null ? type : DEFAULT_TYPE;
        this.title = title != null ? title : (status != null ? HttpStatusHelper.getReasonPhrase(status) : null);
        this.status = status;
        this.detail = detail;
        this.instance = instance;
        this.extensions = extensions != null ? Collections.unmodifiableMap(new LinkedHashMap<>(extensions)) : Collections.emptyMap();
    }

    public URI getType() {
        return type;
    }

    public String getTitle() {
        return title;
    }

    public Integer getStatus() {
        return status;
    }

    public String getDetail() {
        return detail;
    }

    public URI getInstance() {
        return instance;
    }

    public Map<String, Object> getExtensions() {
        return extensions;
    }

    public Object getExtension(String key) {
        return extensions.get(key);
    }

    @SuppressWarnings("unchecked")
    public <T> Optional<T> getExtension(String key, Class<T> type) {
        Object val = extensions.get(key);
        if (val != null && type.isInstance(val)) {
            return Optional.of((T) val);
        }
        return Optional.empty();
    }

    public Map<String, Object> toMap() {
        Map<String, Object> map = new LinkedHashMap<>();
        if (type != null) {
            map.put("type", type.toString());
        }
        if (title != null) {
            map.put("title", title);
        }
        if (status != null) {
            map.put("status", status);
        }
        if (detail != null) {
            map.put("detail", detail);
        }
        if (instance != null) {
            map.put("instance", instance.toString());
        }
        map.putAll(extensions);
        return Collections.unmodifiableMap(map);
    }

    public String toJson() {
        return ProblemJsonCodec.serialize(toMap());
    }

    public static ProblemDetails fromJson(String json) {
        Map<String, Object> map = ProblemJsonCodec.parseJsonObject(json);
        Builder b = builder();

        Object t = map.remove("type");
        if (t != null) {
            b.type(URI.create(t.toString()));
        }

        Object title = map.remove("title");
        if (title != null) {
            b.title(title.toString());
        }

        Object status = map.remove("status");
        if (status instanceof Number n) {
            b.status(n.intValue());
        } else if (status != null) {
            b.status(Integer.parseInt(status.toString()));
        }

        Object detail = map.remove("detail");
        if (detail != null) {
            b.detail(detail.toString());
        }

        Object inst = map.remove("instance");
        if (inst != null) {
            b.instance(URI.create(inst.toString()));
        }

        // Remaining keys are extensions
        b.extensions(map);

        return b.build();
    }

    public static Builder builder() {
        return new Builder();
    }

    public static ProblemDetails forStatus(int status) {
        return builder().status(status).build();
    }

    public static ProblemDetails forStatusAndDetail(int status, String detail) {
        return builder().status(status).detail(detail).build();
    }

    public static ProblemDetails badRequest(String detail) {
        return forStatusAndDetail(400, detail);
    }

    public static ProblemDetails unauthorized(String detail) {
        return forStatusAndDetail(401, detail);
    }

    public static ProblemDetails forbidden(String detail) {
        return forStatusAndDetail(403, detail);
    }

    public static ProblemDetails notFound(String detail) {
        return forStatusAndDetail(404, detail);
    }

    public static ProblemDetails conflict(String detail) {
        return forStatusAndDetail(409, detail);
    }

    public static ProblemDetails unprocessableEntity(String detail) {
        return forStatusAndDetail(422, detail);
    }

    public static ProblemDetails internalServerError(String detail) {
        return forStatusAndDetail(500, detail);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof ProblemDetails that)) return false;
        return Objects.equals(type, that.type) &&
                Objects.equals(title, that.title) &&
                Objects.equals(status, that.status) &&
                Objects.equals(detail, that.detail) &&
                Objects.equals(instance, that.instance) &&
                Objects.equals(extensions, that.extensions);
    }

    @Override
    public int hashCode() {
        return Objects.hash(type, title, status, detail, instance, extensions);
    }

    @Override
    public String toString() {
        return "ProblemDetails{" +
                "type=" + type +
                ", title='" + title + '\'' +
                ", status=" + status +
                ", detail='" + detail + '\'' +
                ", instance=" + instance +
                ", extensions=" + extensions +
                '}';
    }

    public static final class Builder {
        private URI type;
        private String title;
        private Integer status;
        private String detail;
        private URI instance;
        private final Map<String, Object> extensions = new LinkedHashMap<>();

        private Builder() {
        }

        public Builder type(URI type) {
            this.type = type;
            return this;
        }

        public Builder type(String type) {
            this.type = type != null ? URI.create(type) : null;
            return this;
        }

        public Builder title(String title) {
            this.title = title;
            return this;
        }

        public Builder status(int status) {
            this.status = status;
            return this;
        }

        public Builder detail(String detail) {
            this.detail = detail;
            return this;
        }

        public Builder instance(URI instance) {
            this.instance = instance;
            return this;
        }

        public Builder instance(String instance) {
            this.instance = instance != null ? URI.create(instance) : null;
            return this;
        }

        public Builder extension(String key, Object value) {
            if (key != null && !key.isBlank() && value != null) {
                this.extensions.put(key, value);
            }
            return this;
        }

        public Builder extensions(Map<String, ?> exts) {
            if (exts != null) {
                for (Map.Entry<String, ?> entry : exts.entrySet()) {
                    if (entry.getValue() != null) {
                        this.extensions.put(entry.getKey(), entry.getValue());
                    }
                }
            }
            return this;
        }

        @SuppressWarnings("unchecked")
        public Builder invalidParam(String name, String reason) {
            List<InvalidParam> list = (List<InvalidParam>) this.extensions.computeIfAbsent("invalidParams", k -> new ArrayList<InvalidParam>());
            list.add(new InvalidParam(name, reason));
            return this;
        }

        public Builder invalidParams(List<InvalidParam> params) {
            if (params != null && !params.isEmpty()) {
                this.extensions.put("invalidParams", new ArrayList<>(params));
            }
            return this;
        }

        public ProblemDetails build() {
            return new ProblemDetails(type, title, status, detail, instance, extensions);
        }
    }
}
